insert into products (name, name_en, slug, category, price, description, description_en, options, featured, sold, images, created_at)
values
  ('Parure plastron dorée', 'Gold statement necklace set', 'parure-plastron-doree', 'bijoux', 18000, 'Parure complète au fini doré : plastron ciselé, boucles d''oreilles et bague assorties. Idéale pour les mariages, baptêmes et grandes cérémonies.', 'Complete gold-finish set: engraved statement necklace with matching earrings and ring. Perfect for weddings, naming ceremonies and big occasions.', '{}'::text[], true, false, array['/images/produits/parure-plastron-doree.webp']::text[], now() - interval '0 minutes'),
  ('Parure fleurs dorées', 'Gold flower jewellery set', 'parure-fleurs-dorees', 'bijoux', 15000, 'Collier, bracelet et bague aux motifs floraux dorés. Une parure féminine et raffinée qui illumine toutes vos tenues.', 'Necklace, bracelet and ring with gold floral motifs. A feminine, refined set that lights up every outfit.', '{}'::text[], true, false, array['/images/produits/parure-fleurs-dorees.webp']::text[], now() - interval '1 minutes'),
  ('Ensemble indien doré', 'Gold Indian-style set', 'ensemble-indien-dore', 'bijoux', 20000, 'Ensemble de style indien : double collier à perles dorées, grandes boucles d''oreilles et bague ajourée.', 'Indian-style set: double gold bead necklace, large earrings and an openwork ring.', '{}'::text[], true, false, array['/images/produits/ensemble-indien-dore.webp']::text[], now() - interval '2 minutes'),
  ('Collier torque & créoles dorées', 'Gold torque necklace & hoops', 'collier-torque-creoles-dorees', 'bijoux', 9000, 'Collier torque en fils dorés superposés accompagné de ses créoles assorties. Élégant et moderne.', 'Layered gold wire torque necklace with matching hoop earrings. Elegant and modern.', '{}'::text[], false, false, array['/images/produits/collier-torque-creoles-dorees.webp']::text[], now() - interval '3 minutes'),
  ('Parure collier perles dorées', 'Gold bead necklace set', 'parure-collier-perles-dorees', 'bijoux', 12000, 'Collier de perles dorées avec pendentifs et boucles d''oreilles pendantes assorties.', 'Gold bead necklace with pendants and matching drop earrings.', '{}'::text[], false, false, array['/images/produits/parure-collier-perles-dorees.webp']::text[], now() - interval '4 minutes'),
  ('Bracelet jonc doré ciselé', 'Engraved gold bangle', 'bracelet-jonc-dore-cisele', 'bijoux', 5000, 'Bracelet jonc large au fini doré, finement ciselé. Se porte seul ou en accumulation.', 'Wide gold-finish bangle with fine engraving. Wear it alone or stacked.', '{}'::text[], false, false, array['/images/produits/bracelet-jonc-dore-cisele.webp']::text[], now() - interval '5 minutes'),
  ('Bracelet manchette cœur', 'Heart cuff bracelet', 'bracelet-manchette-coeur-doree', 'bijoux', 6000, 'Manchette dorée à maillons travaillés, ornée d''un cœur. Un bijou délicat pour tous les jours.', 'Gold cuff with detailed links and a heart charm. A delicate everyday piece.', '{}'::text[], false, false, array['/images/produits/bracelet-manchette-coeur-doree.webp']::text[], now() - interval '6 minutes'),
  ('Bague & manchette dorées', 'Gold ring & cuff', 'bague-bracelet-manchette-dores', 'bijoux', 7500, 'Duo bague et bracelet manchette dorés aux motifs gravés, pour une touche de caractère.', 'Gold ring and cuff bracelet duo with engraved patterns, for a touch of character.', '{}'::text[], false, false, array['/images/produits/bague-bracelet-manchette-dores.webp']::text[], now() - interval '7 minutes'),
  ('Boucles d''oreilles mosaïque', 'Gold mosaic earrings', 'boucles-oreilles-mosaique-dorees', 'bijoux', 3500, 'Boucles d''oreilles rondes dorées à éclats colorés, légères et lumineuses.', 'Round gold earrings with colourful accents, light and luminous.', '{}'::text[], false, false, array['/images/produits/boucles-oreilles-mosaique-dorees.webp']::text[], now() - interval '8 minutes'),
  ('Perruque carré rouge', 'Red bob wig', 'perruque-carre-rouge', 'perruques', 25000, 'Perruque coupe carré couleur rouge intense, coiffée dans notre salon. Un look audacieux prêt à porter.', 'Bold red bob wig, styled in our salon. A striking look, ready to wear.', '{}'::text[], true, false, array['/images/produits/perruque-carre-rouge.webp']::text[], now() - interval '9 minutes'),
  ('Perruque ondulée noire', 'Black wavy wig', 'perruque-ondulee-noire', 'perruques', 30000, 'Perruque mi-longue aux ondulations naturelles, couleur noire. Volume et mouvement garantis.', 'Mid-length black wig with natural waves. Volume and movement guaranteed.', '{}'::text[], true, false, array['/images/produits/perruque-ondulee-noire.webp']::text[], now() - interval '10 minutes'),
  ('Perruque lisse noire', 'Black straight wig', 'perruque-lisse-noire', 'perruques', 30000, 'Perruque lisse noire mi-longue avec baby hair travaillés. Un rendu naturel et soigné.', 'Mid-length straight black wig with styled baby hair. A natural, polished finish.', '{}'::text[], false, false, array['/images/produits/perruque-lisse-noire.webp']::text[], now() - interval '11 minutes'),
