  ('Perruque carré noir', 'Black bob wig', 'perruque-carre-noir-frange', 'perruques', 25000, 'Carré plongeant noir aux reflets bleutés, coiffé et prêt à porter.', 'Black angled bob with blue-toned shine, styled and ready to wear.', '{}'::text[], false, false, array['/images/produits/perruque-carre-noir-frange.webp']::text[], now() - interval '13 minutes'),
  ('Perruques lace frontal', 'Lace-front wigs', 'duo-perruques-lace', 'perruques', 35000, 'Perruques lace frontal disponibles en carré lisse ou en longueur bouclée. Précisez votre modèle.', 'Lace-front wigs available as a straight bob or long curly style. Tell us which model you want.', array['Carré lisse', 'Bouclée longue']::text[], false, false, array['/images/produits/duo-perruques-lace.webp']::text[], now() - interval '14 minutes'),
  ('Gamme capillaire Boushra', 'Boushra hair care range', 'gamme-capillaire-boushra', 'soins', 10000, 'La gamme capillaire Boushra : sérums et baumes pour nourrir, fortifier et faire briller vos cheveux.', 'The Boushra hair care range: serums and balms to nourish, strengthen and add shine to your hair.', '{}'::text[], true, false, array['/images/produits/gamme-capillaire-boushra.webp']::text[], now() - interval '15 minutes'),
  ('Baume capillaire Boushra', 'Boushra hair balm', 'baume-capillaire-boushra', 'soins', 3000, 'Baume capillaire Boushra aux ingrédients nourrissants, pour des cheveux doux et des pointes protégées.', 'Boushra hair balm with nourishing ingredients, for soft hair and protected ends.', '{}'::text[], false, false, array['/images/produits/baume-capillaire-boushra.webp']::text[], now() - interval '16 minutes'),
