  ('Sac matelassé vieux rose + pochette', 'Dusty-pink quilted bag + clutch', 'sac-matelasse-vieux-rose', 'sacs', 17500, 'Sac à main matelassé couleur vieux rose, livré avec sa pochette assortie.', 'Dusty-pink quilted handbag, sold with its matching clutch.', '{}'::text[], true, false, array['/images/produits/sac-matelasse-vieux-rose.webp']::text[], now() - interval '19 minutes'),
  ('Sac hobo jaune effet croco', 'Yellow croc-effect hobo bag', 'sac-hobo-jaune-croco', 'sacs', 15000, 'Sac hobo souple jaune effet croco avec fermoir cadenas doré. Une pièce forte pour vos tenues.', 'Soft yellow croc-effect hobo bag with a gold padlock clasp. A statement piece for your outfits.', '{}'::text[], false, false, array['/images/produits/sac-hobo-jaune-croco.webp']::text[], now() - interval '20 minutes'),
